/* Fishing Port Access Gaps · interactive map (T5.1).
 * Static: reads data/*.json|geojson generated by src/portgaps/map/build_map_data.py
 * from the frozen results. No analysis happens here; every number is read from
 * the data files. Display rules (decisions log, report language rule):
 *   value = range across main and s1 runs (s1 = lower bound on stranding);
 *   "holds under both runs" entries carry no range caveat; s4 = labelled sensitivity.
 */
(function () {
  'use strict';

  var SVC = { fuel: 'Fuel', ice: 'Ice', hoist_crane: 'Hoist/crane', cold_storage: 'Cold storage' };
  var SVC_LC = { fuel: 'fuel', ice: 'ice', hoist_crane: 'hoist/crane', cold_storage: 'cold storage' };
  var STATUS = { available: 'Available', not_available: 'Not available', closed: 'Closed', not_found: 'No source located' };
  var RUN_LABEL = { main: 'main run', s1: 's1 (unverified cells treated as available)', s4: 's4 sensitivity' };
  var C = { blue: '#0072B2', orange: '#D55E00', green: '#009E73', purple: '#CC79A7', grey: '#6b7280', ink: '#1b1f23' };

  var state = { service: 'fuel', t: '40', s4: false, events: true, harbor: null, facility: null };
  var H = {}, HARBORS = [], IDX = null, EVENTS = [], EV_BY_HARBOR = {};
  var routes = null, routesLoading = null;
  var map, markers = {}, routeLayer;

  // ---------- helpers ----------
  function $(s) { return document.querySelector(s); }
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function safeUrl(u) { return /^https?:\/\//i.test(u || '') ? u : null; }
  function m(v) { if (v === 0) return '0'; var x = v / 1e6; return x < 1 ? x.toFixed(2) : x.toFixed(1); }
  function money(v) { return v === 0 ? '$0' : '$' + m(v) + 'M'; }
  function range(r) { return r[0] === r[1] ? money(r[0]) : '$' + m(r[0]) + '–' + m(r[1]) + 'M'; }
  function name(id) { return (H[id] && H[id].name) || IDX.harbor_names[id] || id; }
  function shortName(id) { return name(id).replace(/\s*\(.*\)\s*$/, ''); }
  function activeRun() { return state.s4 ? 's4' : 'main'; }
  function facAt(fid) { var f = IDX.facilities[fid]; return f ? f.t[state.t] : null; }
  function sameList(a, b) { return JSON.stringify(a) === JSON.stringify(b); }
  function names(ids) { return ids.length ? ids.map(shortName).join(', ') : 'none'; }

  // ---------- markers ----------
  function shape(st) {
    if (st === 'available') return '<circle r="7" fill="' + C.blue + '" stroke="#fff" stroke-width="2"/><circle r="8.5" fill="none" stroke="' + C.blue + '" stroke-width="1"/>';
    if (st === 'not_available') return '<circle r="6" fill="#fff" stroke="' + C.orange + '" stroke-width="3"/>';
    if (st === 'closed') return '<circle r="7.5" fill="#000"/><path d="M-3.5-3.5L3.5 3.5M3.5-3.5L-3.5 3.5" stroke="#fff" stroke-width="2"/>';
    return '<circle r="6" fill="#fff" stroke="' + C.grey + '" stroke-width="2" stroke-dasharray="3 2"/>';
  }
  function rankFor(id) {
    var f = facAt(id + '|' + state.service); if (!f) return null;
    var r = f[activeRun()];
    return (r.rank <= 10 && r.high > 0) ? r.rank : null;
  }
  function cutSet() {
    if (!state.facility) return {};
    var f = facAt(state.facility); if (!f) return {};
    var o = {}; f[activeRun()].cut.forEach(function (h) { o[h] = 1; }); return o;
  }
  function iconFor(h, cut) {
    var st = h.services[state.service].status;
    var ring = '';
    if (cut[h.id]) ring += '<circle r="11.5" fill="none" stroke="' + C.orange + '" stroke-width="2" stroke-dasharray="3 2"/>';
    if (state.harbor === h.id) ring += '<circle r="11.5" fill="none" stroke="' + C.ink + '" stroke-width="3"/>';
    var rk = rankFor(h.id);
    var ev = state.events && EV_BY_HARBOR[h.id] ?
      '<g transform="translate(-13,-14)"><path d="M6 0L12 10.5H0Z" fill="' + C.purple + '" stroke="#fff" stroke-width="1.2"/><path d="M6 3.5v3.3" stroke="#fff" stroke-width="1.6"/><circle cx="6" cy="8.6" r=".9" fill="#fff"/></g>' : '';
    var html = '<svg width="26" height="26" viewBox="-13 -13 26 26" aria-hidden="true">' + ring + shape(st) + ev + '</svg>' +
      (rk ? '<span class="rank">' + rk + '</span>' : '');
    return L.divIcon({ className: 'hm', html: html, iconSize: [26, 26], iconAnchor: [13, 13] });
  }
  function markerTitle(h) {
    var st = h.services[state.service];
    var rk = rankFor(h.id);
    var ev = state.events && EV_BY_HARBOR[h.id] ? '; validation closure: ' + EV_BY_HARBOR[h.id].map(function (e) { return e.label; }).join(', ') : '';
    return h.name + ', ' + h.state + ': ' + SVC_LC[state.service] + ' ' + STATUS[st.status].toLowerCase() +
      (rk ? ', top-10 rank ' + rk : '') + ev;
  }
  // Keyboard activation for focusable markers (Enter / Space), deduplicated
  // against any click Leaflet may synthesise from the same key press.
  var lastKey = 0;
  function onActivate(mk, fn) {
    mk.on('click', function () { if (Date.now() - lastKey > 400) fn(); });
    mk.on('add', function () {
      var el = mk.getElement(); if (!el || el._kb) return; el._kb = true;
      el.addEventListener('keydown', function (e) {
        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); e.stopPropagation(); lastKey = Date.now(); fn(); }
      });
    });
  }
  function refreshMarkers() {
    var cut = cutSet();
    var focusedId = null;
    HARBORS.forEach(function (h) {
      var mk = markers[h.id];
      if (document.activeElement && document.activeElement === mk.getElement()) focusedId = h.id;
      mk.setIcon(iconFor(h, cut));
      var el = mk.getElement();
      if (el) { el.setAttribute('title', markerTitle(h)); el.setAttribute('aria-label', markerTitle(h)); }
      mk.setZIndexOffset(state.harbor === h.id ? 1000 : (rankFor(h.id) || (state.events && EV_BY_HARBOR[h.id]) ? 500 : 0));
    });
    if (focusedId) markers[focusedId].getElement().focus({ preventScroll: true });
  }

  // ---------- routes ----------
  function loadRoutes() {
    if (routes) return Promise.resolve(routes);
    if (!routesLoading) {
      routesLoading = fetch('data/routes.geojson').then(function (r) { return r.json(); }).then(function (g) {
        routes = {};
        g.features.forEach(function (f) {
          var k = [f.properties.a, f.properties.b].sort().join('~');
          routes[k] = f.geometry.coordinates.map(function (c) { return [c[1], c[0]]; });
        });
        return routes;
      });
    }
    return routesLoading;
  }
  function drawRoutes(fit) {
    routeLayer.clearLayers();
    if (!state.facility) return;
    var f = facAt(state.facility); if (!f) return;
    var run = activeRun(), T = +state.t;
    var bk = f[run].backups;
    loadRoutes().then(function (R) {
      if (!state.facility || facAt(state.facility) !== f || activeRun() !== run) return;
      routeLayer.clearLayers();
      var pts = [];
      bk.forEach(function (b) {
        if (!b[1]) return;
        var line = R[[b[0], b[1]].sort().join('~')];
        if (!line) return;
        var within = b[2] <= T + 1e-9;
        L.polyline(line, {
          color: within ? C.green : C.orange, weight: 4, opacity: .9,
          dashArray: within ? null : '8 6', interactive: true
        }).bindTooltip(shortName(b[0]) + ' → ' + shortName(b[1]) + ': ' + b[2].toFixed(1) + ' nm' +
          (within ? ' (within ' + T + ' nm)' : ' (beyond ' + T + ' nm: cut off)'), { sticky: true })
          .addTo(routeLayer);
        pts = pts.concat(line);
      });
      if (fit && pts.length) map.fitBounds(L.latLngBounds(pts), { padding: [40, 40], maxZoom: 10 });
    }).catch(function () { /* routes are optional; the panel text still lists backups */ });
  }

  // ---------- panels ----------
  function statusCell(s) {
    return '<span class="st"><span class="sym" data-st="' + s.status + '" aria-hidden="true"></span>' + STATUS[s.status] + '</span>';
  }
  function backupText(b, T, run) {
    if (!b[1]) return esc(shortName(b[0])) + ': no backup hoist at any distance (no moorage; ' + RUN_LABEL[run] + ')';
    var within = b[2] <= T + 1e-9;
    return esc(shortName(b[0])) + ' → ' + esc(shortName(b[1])) + ', ' + b[2].toFixed(1) + ' nm ' +
      (within ? '(within ' + T + ' nm)' : '<strong>(beyond ' + T + ' nm: cut off)</strong>');
  }
  function facilityBlock(fid) {
    var f = facAt(fid), svc = fid.split('|')[1], T = +state.t;
    var mn = f.main, s1 = f.s1, s4 = f.s4;
    var head = '<p><strong>' + SVC[svc] + '</strong> at ' + T + ' nm: ';
    if (mn.high === 0 && s1.high === 0) {
      head += '<span class="val">' + money(0) + '</span> stranded</p>' +
        '<p>' + (mn.cut.length ? 'Cuts off ' + esc(names(mn.cut)) + ', with no published landed value.'
          : 'No harbor is cut off: every harbor it serves has another ' + SVC_LC[svc] + ' facility within ' + T + ' nm.') +
        (state.s4 ? ' <span class="hint">(main and s1 runs)</span>' : '') + '</p>';
    } else {
      head += '<span class="val">' + range(f.range) + '</span> stranded ';
      if (f.hold) head += '<span class="badge hold">Holds under both runs</span>';
      else if (f.top10) head += '<span class="badge caveat">Range: rests on unverified cells</span>';
      head += '</p>';
      head += '<p>Rank among ' + SVC_LC[svc] + ' facilities: main #' + mn.rank +
        (s1.high > 0 ? ' · s1 #' + s1.rank : ' · s1: none stranded') + '</p>';
      if (!f.hold && f.range[0] !== f.range[1])
        head += '<p class="hint">The range covers two uncertainties: unverified "no source located" cells (the s1 run treats them as available) and landings published only for a shared agency group (the lower end counts only the harbor\'s own published value).</p>';
      head += '<p>Would cut off: ' + esc(names(mn.cut)) + '</p>';
      if (!sameList(mn.cut, s1.cut)) head += '<p class="hint">Under s1: ' + esc(names(s1.cut)) + '</p>';
    }
    var run = activeRun();
    var bk = f[run].backups.map(function (b) { return '<li>' + backupText(b, T, run) + '</li>'; }).join('');
    head += '<p>Nearest backup' + (f[run].backups.length > 1 ? 's' : '') + (state.s4 ? ' (s4)' : '') + ':</p><ul>' + bk + '</ul>';
    if (!state.s4 && !sameList(mn.backups, s1.backups)) {
      head += '<p class="hint">Under s1: ' + s1.backups.filter(function (b) { return b[1]; }).map(function (b) {
        return esc(shortName(b[0])) + ' → ' + esc(shortName(b[1])) + ' ' + b[2].toFixed(1) + ' nm';
      }).join('; ') + '</p>';
    }
    if (state.s4 && (s4.high !== mn.high || s4.low !== mn.low || !sameList(s4.cut, mn.cut))) {
      head += '<p><span class="badge s4">s4 sensitivity</span> ' + range([s4.low, s4.high]) +
        (s4.high > 0 ? ', rank #' + s4.rank : '') + '; cuts off ' + esc(names(s4.cut)) + '</p>';
    }
    var pressed = state.facility === fid;
    head += '<button type="button" class="btn" data-fac="' + esc(fid) + '" aria-pressed="' + pressed + '">' +
      (pressed ? 'Backup routes shown · zoom to them' : 'Show backup routes') + '</button>';
    return '<div class="idx">' + head + '</div>';
  }
  function eventBlock(ev) {
    var T = state.t;
    return ev.cells.map(function (c) {
      var v = c.verdicts[T];
      var out = '<div class="ev"><p><strong>Validation closure: ' + esc(c.event.replace(/^E\d+[ab]? /, '')) + '</strong> · ' + esc(c.dates) + '</p>';
      out += '<p><span class="verdict">' + esc(v.main.verdict) + '</span> at ' + T + ' nm (main): ' + esc(v.main.reason) + '</p>';
      if (v.s1.verdict !== v.main.verdict || v.s1.reason !== v.main.reason)
        out += '<p><span class="verdict">' + esc(v.s1.verdict) + '</span> under s1: ' + esc(v.s1.reason) + '</p>';
      if (v.s4.verdict !== v.main.verdict || v.s4.reason !== v.main.reason)
        out += '<p><span class="badge s4">s4 sensitivity</span> <span class="verdict">' + esc(v.s4.verdict) + '</span>: ' + esc(v.s4.reason) + '</p>';
      if (c.documented_backup) out += '<p class="hint">Documented backup: ' + esc(shortName(c.documented_backup)) + ', ' + Number(c.documented_backup_nm).toFixed(1) + ' nm.</p>';
      if (c.restored_for_review) out += '<p class="hint">Review step: the failed cell was set back to "available" before removal; the index itself is unchanged.</p>';
      return out + '</div>';
    }).join('');
  }
  function renderDetail(focus) {
    var el = $('#detail');
    if (!state.harbor) { el.hidden = true; el.innerHTML = ''; return; }
    var h = H[state.harbor];
    var html = '<div class="detail-head"><h2 tabindex="-1">' + esc(h.name) + ' <span class="hint">' + esc(h.county) + ' Co., ' + esc(h.state) + '</span></h2>' +
      '<button type="button" class="close" id="detail-close" aria-label="Close harbor details">×</button></div>';
    (EV_BY_HARBOR[h.id] || []).forEach(function (ev) { html += eventBlock(ev); });
    html += '<h3>Services (current status)</h3><table class="svc"><thead><tr><th scope="col">Service</th><th scope="col">Status</th><th scope="col">Confidence</th><th scope="col">As of</th><th scope="col">Source</th></tr></thead><tbody>';
    Object.keys(SVC).forEach(function (s) {
      var x = h.services[s], u = safeUrl(x.source_url);
      html += '<tr' + (s === state.service ? ' class="cur"' : '') + '><th scope="row">' + SVC[s] + '</th><td>' + statusCell(x) + '</td><td>' +
        esc(x.confidence) + '</td><td>' + esc(x.as_of_date) + '</td><td>' +
        (u ? '<a href="' + esc(u) + '" target="_blank" rel="noopener noreferrer">' + esc(x.source_type || 'source') + '</a>'
          : esc(x.source_type || '—')) + '</td></tr>';
    });
    html += '</tbody></table>';
    html += '<h3>Single-point-of-failure index</h3>';
    var order = [state.service].concat(Object.keys(SVC).filter(function (s) { return s !== state.service; }));
    var any = false;
    order.forEach(function (s) {
      var fid = h.id + '|' + s;
      if (IDX.facilities[fid]) { html += facilityBlock(fid); any = true; }
      else if (s === state.service) html += '<p class="hint">No working ' + SVC_LC[s] + ' facility here (' + STATUS[h.services[s].status].toLowerCase() + '), so there is nothing to remove for this service.</p>';
    });
    if (!any) html += '<p class="hint">This harbor has no facility counted as working in the main run.</p>';
    el.innerHTML = html; el.hidden = false;
    $('#detail-close').addEventListener('click', function () { select(null); });
    el.querySelectorAll('button[data-fac]').forEach(function (b) {
      b.addEventListener('click', function () {
        state.facility = b.getAttribute('data-fac');
        update({ fitRoutes: true });
      });
    });
    if (focus) el.querySelector('h2').focus({ preventScroll: false });
  }
  function renderTop10() {
    var s = state.service, run = activeRun(), T = state.t;
    var rows = [];
    Object.keys(IDX.facilities).forEach(function (fid) {
      var f = IDX.facilities[fid]; if (f.service !== s) return;
      var t = f.t[T], r = t[run];
      if (r.rank <= 10 && r.high > 0) rows.push({ fid: fid, f: f, t: t, r: r });
    });
    rows.sort(function (a, b) { return a.r.rank - b.r.rank || name(a.f.harbor).localeCompare(name(b.f.harbor)); });
    var html = '<h2>Top 10 · ' + SVC[s] + ' at ' + T + ' nm' + (state.s4 ? ' <span class="badge s4">s4 sensitivity</span>' : '') + '</h2>' +
      '<p class="hint">' + (state.s4
        ? 's4 ranking: like the main run, but Point Arena and Port Orford can only use their own hoist. Values are the s4 run\'s lower–upper landed value; other services are identical to the main run.'
        : 'Ranked by lower-bound stranded value, main run. Values are the range across main and s1.') + '</p><ol class="top">';
    rows.forEach(function (x) {
      var val = state.s4 ? range([x.r.low, x.r.high]) : range(x.t.range);
      var badge = state.s4 ? '' : (x.t.hold ? ' <span class="badge hold" title="Holds under both runs">holds</span>' : '');
      html += '<li><button type="button" data-fac="' + esc(x.fid) + '"' + (state.facility === x.fid ? ' aria-current="true"' : '') + '>' +
        '<span class="rk">' + x.r.rank + '</span><span>' + esc(shortName(x.f.harbor)) + ' <span class="hint">' + esc(H[x.f.harbor].state) + '</span>' + badge + '</span>' +
        '<span class="v">' + val + '</span></button></li>';
    });
    html += '</ol>';
    if (!rows.length) html += '<p>No facility strands landed value at this threshold.</p>';
    var el = $('#top10'); el.innerHTML = html;
    el.querySelectorAll('button[data-fac]').forEach(function (b) {
      b.addEventListener('click', function () {
        var fid = b.getAttribute('data-fac');
        state.harbor = fid.split('|')[0]; state.facility = fid;
        update({ fitRoutes: true, focusDetail: true });
      });
    });
  }

  // ---------- state ----------
  function select(harborId) {
    state.harbor = harborId;
    var fid = harborId ? harborId + '|' + state.service : null;
    state.facility = fid && IDX.facilities[fid] ? fid : null;
    update({});
  }
  function writeHash() {
    var p = ['s=' + state.service, 't=' + state.t];
    if (state.s4) p.push('s4=1');
    if (!state.events) p.push('ev=0');
    if (state.harbor) p.push('h=' + state.harbor);
    if (state.facility && state.facility.split('|')[0] !== state.harbor) p.push('f=' + state.facility);
    try { history.replaceState(null, '', '#' + p.join('&')); } catch (e) { /* file:// or sandbox */ }
  }
  function readHash() {
    var q = {};
    location.hash.replace(/^#/, '').split('&').forEach(function (kv) { var i = kv.indexOf('='); if (i > 0) q[kv.slice(0, i)] = decodeURIComponent(kv.slice(i + 1)); });
    if (SVC[q.s]) state.service = q.s;
    if (IDX.meta.thresholds.indexOf(+q.t) >= 0) state.t = String(+q.t);
    state.s4 = q.s4 === '1';
    state.events = q.ev !== '0';
    if (q.h && H[q.h]) { state.harbor = q.h; var fid = q.h + '|' + state.service; state.facility = IDX.facilities[fid] ? fid : null; }
    document.querySelector('input[name=service][value="' + state.service + '"]').checked = true;
    document.querySelector('input[name=threshold][value="' + state.t + '"]').checked = true;
    $('#s4').checked = state.s4; $('#events').checked = state.events;
  }
  function update(opt) {
    opt = opt || {};
    if (state.facility && state.facility.split('|')[1] !== state.service) {
      var fid = state.harbor ? state.harbor + '|' + state.service : null;
      state.facility = fid && IDX.facilities[fid] ? fid : null;
    }
    refreshMarkers();
    renderDetail(opt.focusDetail);
    renderTop10();
    drawRoutes(opt.fitRoutes);
    writeHash();
  }

  // ---------- init ----------
  function init(hg, idx, ev) {
    IDX = idx; EVENTS = ev.events;
    hg.features.forEach(function (f) {
      var p = f.properties; p.lat = f.geometry.coordinates[1]; p.lon = f.geometry.coordinates[0];
      H[p.id] = p; HARBORS.push(p);
    });
    EVENTS.forEach(function (e) { (EV_BY_HARBOR[e.harbor] = EV_BY_HARBOR[e.harbor] || []).push(e); });
    $('#asof-range').textContent = idx.meta.facility_as_of_range.join(' to ');
    $('#build-info').textContent = idx.meta.results_tag + ', inputs at commit ' + idx.meta.built_from_commit;

    map = L.map('map', { zoomControl: true, keyboard: true, preferCanvas: false, minZoom: 4, maxZoom: 16 });
    map.attributionControl.setPrefix('<a href="https://leafletjs.com">Leaflet</a>');
    L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19,
      attribution: '© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors (ODbL)'
    }).addTo(map);
    map.attributionControl.addAttribution('Routes from OSM (ODbL) · Data: CDFW, ODFW, PacFIN, NOAA');
    routeLayer = L.layerGroup().addTo(map);

    readHash();
    var cut = cutSet();
    HARBORS.forEach(function (h) {
      var mk = L.marker([h.lat, h.lon], { icon: iconFor(h, cut), keyboard: true, title: markerTitle(h), riseOnHover: true });
      onActivate(mk, function () { select(state.harbor === h.id ? null : h.id); });
      mk.addTo(map); markers[h.id] = mk;
    });
    map.fitBounds(L.latLngBounds(HARBORS.map(function (h) { return [h.lat, h.lon]; })), { padding: [20, 20] });

    document.querySelectorAll('input[name=service]').forEach(function (r) {
      r.addEventListener('change', function () { state.service = r.value; update({}); });
    });
    document.querySelectorAll('input[name=threshold]').forEach(function (r) {
      r.addEventListener('change', function () { state.t = r.value; update({}); });
    });
    $('#s4').addEventListener('change', function (e) { state.s4 = e.target.checked; update({}); });
    $('#events').addEventListener('change', function (e) { state.events = e.target.checked; update({}); });
    var dlg = $('#about');
    $('#about-open').addEventListener('click', function () { if (dlg.showModal) dlg.showModal(); else dlg.setAttribute('open', ''); });
    $('#about-close').addEventListener('click', function () { if (dlg.close) dlg.close(); else dlg.removeAttribute('open'); });
    dlg.addEventListener('click', function (e) { if (e.target === dlg && dlg.close) dlg.close(); });
    document.addEventListener('keydown', function (e) { if (e.key === 'Escape' && state.harbor && !dlg.open) select(null); });

    update({ fitRoutes: false });
  }

  Promise.all(['data/harbors.geojson', 'data/index.json', 'data/events.json'].map(function (u) {
    return fetch(u).then(function (r) { if (!r.ok) throw new Error(u + ' ' + r.status); return r.json(); });
  })).then(function (d) { init(d[0], d[1], d[2]); }).catch(function (err) {
    var el = document.getElementById('detail');
    el.hidden = false;
    el.textContent = 'The map data could not be loaded (' + err.message + '). Please reload the page.';
  });
})();
